/* istanbul ignore file */
'use strict'

const FJS = require('fast-json-stringify')
const path = require('node:path')
const fs = require('node:fs')

// The upstream package the generated error serializer is built from. It is a
// **build time** dependency only: the generated file is committed and it does
// not require the package at runtime.
const upstreamName = 'fast-json-stringify'
const upstreamRequire = `const Serializer = require('${upstreamName}/lib/serializer')`
const upstreamExport = 'module.exports = class Serializer {'
const upstreamLicense = 'MIT'

// The schema of the built-in error serializer: it must not change, the bytes
// of the error bodies are the contract.
const schema = {
  type: 'object',
  properties: {
    statusCode: { type: 'number' },
    code: { type: 'string' },
    error: { type: 'string' },
    message: { type: 'string' }
  }
}

/* c8 ignore start */
function readUpstream () {
  const packagePath = require.resolve(`${upstreamName}/package.json`)
  const serializerPath = require.resolve(`${upstreamName}/lib/serializer`)

  const pkg = JSON.parse(fs.readFileSync(packagePath, 'utf8'))
  const source = fs.readFileSync(serializerPath, 'utf8')

  if (pkg.license !== upstreamLicense) {
    throw new Error(
      `The upstream package '${upstreamName}' is licensed under '${pkg.license}', ` +
      `the generated error serializer expects '${upstreamLicense}'`
    )
  }

  if (!source.includes(upstreamExport)) {
    throw new Error(
      `The serializer of '${upstreamName}' does not have the expected shape: ` +
      `'${upstreamExport}' was not found in '${serializerPath}'`
    )
  }

  return { version: pkg.version, source }
}

/**
 * The upstream serializer is a CommonJS module: `module.exports = class
 * Serializer { … }`. The generated file is a plain script, so the export is
 * turned into a class declaration. The rest of the source is copied verbatim.
 */
function toClassDeclaration (source) {
  return source.replace(upstreamExport, 'class Serializer {')
}

/**
 * The standalone output of `fast-json-stringify` requires the package at
 * runtime. The serializer class is inlined instead, so that the generated file
 * is self contained: it requires nothing outside of the repository.
 */
function inlineSerializer (standalone, source) {
  if (!standalone.includes(upstreamRequire)) {
    throw new Error(
      `The standalone output of '${upstreamName}' does not have the expected shape: ` +
      `'${upstreamRequire}' was not found`
    )
  }

  return standalone.replace(upstreamRequire, toClassDeclaration(source).trimEnd())
}

function buildHeader (version) {
  return `// This file is autogenerated by build/build-error-serializer.js, do not edit
//
// It is the '${upstreamName}' standalone output (version ${version}) plus an
// inlined copy of the serializer class of the '${upstreamName}' package
// (version ${version}), so that the built-in error serializer does not require
// '${upstreamName}' at runtime.
//
// The inlined copy is distributed under the ${upstreamLicense} licence of the
// upstream '${upstreamName}' package, Copyright (c) the Fastify organisation:
// https://github.com/fastify/${upstreamName}/blob/main/LICENSE
`
}
/* c8 ignore stop */

/**
 * The version of the upstream package the committed artefact is built from.
 *
 * The devDependency is pinned to that **exact** version: the generated file
 * embeds the version and the inlined source of the upstream package, so a
 * patch release of the upstream package would change the bytes of the
 * committed file and break the integrity gate.
 */
function readPinnedVersion () {
  const pkgPath = path.join(__dirname, '..', 'package.json')
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'))
  return pkg.devDependencies[upstreamName]
}

/**
 * The installed version of the upstream package must be the pinned one.
 *
 * @param {string} version the version of the installed upstream package
 * @param {string} pinned the version the devDependency is pinned to
 * @throws {Error} when the installed version is not the pinned one
 */
function assertPinnedVersion (version, pinned) {
  if (version !== pinned) {
    throw new Error(
      `The installed version of '${upstreamName}' is '${version}' but the devDependency is pinned to '${pinned}'. ` +
      'Install the pinned version (npm install) and regenerate the committed artefact ' +
      'with npm run build:error-serializer.'
    )
  }
}

function buildModuleCode () {
  const { version, source } = readUpstream()
  assertPinnedVersion(version, readPinnedVersion())
  const standalone = FJS(schema, { mode: 'standalone' })
  const inlined = inlineSerializer(standalone, source)

  // The whole module — the standalone output and the inlined copy of the
  // serializer class — lives inside the `c8 ignore` region: the generated
  // file is not part of the coverage gate.
  return `${buildHeader(version)}/* c8 ignore start */
${inlined}
/* c8 ignore stop */
`
}

const file = path.join(__dirname, '..', 'lib', 'error-serializer.js')

/* c8 ignore start */
let moduleCode
try {
  moduleCode = buildModuleCode()
} catch (error) {
  if (require.main === module) {
    console.error(`Failed to build the error serializer: ${error.message}`)
    process.exit(1)
  }
  throw error
}

if (require.main === module) {
  fs.writeFileSync(file, moduleCode)
  console.log(`Saved ${file} file successfully`)
} else {
  module.exports = {
    code: moduleCode,
    assertPinnedVersion
  }
}
/* c8 ignore stop */
